 93	// Round robin: the next RUNNABLE process after the last one chosen,
 94	// scanning proc[] in a circle so no process is starved.
 95	static struct proc *
 96	pick_rr(void)
 97	{
 98	  for (int i = 1; i <= NPROC; i++) {
 99	    struct proc *p = &proc[(last + i) % NPROC];
100	    if (p->state == RUNNABLE) {
101	      last = p - proc;
102	      return p;
103	    }
104	  }
105	  return 0;
106	}
