108	// Strict priority: a RUNNABLE process with the lowest nice value;
109	// processes with equal nice take turns in round-robin order.
110	static struct proc *
111	pick_prio(void)
112	{
113	  int best = 100;
114	
115	  for (struct proc *p = proc; p < &proc[NPROC]; p++)
116	    if (p->state == RUNNABLE && p->nice < best)
117	      best = p->nice;
118	  for (int i = 1; i <= NPROC; i++) {
119	    struct proc *p = &proc[(last + i) % NPROC];
120	    if (p->state == RUNNABLE && p->nice == best) {
121	      last = p - proc;
122	      return p;
123	    }
124	  }
125	  return 0;
126	}
