442	// Project 1C: this is the scheduler framework. It owns the locking
443	// and the context switch; the choice of process is made by
444	// policy_pick_next_proc(). You should not need to modify it.
445	void
446	scheduler(void)
447	{
448	  struct proc *p;
449	  struct cpu *c = mycpu();
450	
451	  c->proc = 0;
452	  for (;;) {
453	    // The most recent process to run may have had interrupts
454	    // turned off; enable them to avoid a deadlock if all
455	    // processes are waiting. Then turn them back off
456	    // to avoid a possible race between an interrupt
457	    // and wfi.
458	    intr_on();
459	    intr_off();
460	
461	    p = policy_pick_next_proc();
462	    if (p == 0) {
463	      // nothing to run; stop running on this core until an interrupt.
464	      asm volatile("wfi");
465	      continue;
466	    }
467	
468	    acquire(&p->lock);
469	    if (p->state == RUNNABLE) {
470	      // Switch to chosen process.  It is the process's job
471	      // to release its lock and then reacquire it
472	      // before jumping back to us.
473	      p->state = RUNNING;
474	      c->proc = p;
475	      policy_dispatch(p);
476	      wl_dispatch(p);
477	      // While a workload is loaded, log only its workers, so other
478	      // processes (such as a pause() loop, woken every tick) do not
479	      // bury their lines.
480	      if (logging && (!wl_loaded() || p->wl_slot >= 0))
481	        printk("running %d at %d\n", p->pid, ticks);
482	      swtch(&c->context, &p->context);
483	
484	      // Don't re-enable interrupts on release.
485	      mycpu()->intena = 0;
486	
487	      // Process is done running for now.
488	      // It should have changed its p->state before coming back.
489	      c->proc = 0;
490	    }
491	    release(&p->lock);
492	  }
493	}
