    66	// Mark slot s ready to run a new CPU burst at tick now.
    67	// Caller holds wl_lock.
    68	static void
    69	make_ready(struct wl_state *s, int now)
    70	{
    71	  s->phase = WL_CPU;
    72	  s->remaining = s->def.cpu_burst * TICK_UNITS;
    73	  s->ready_at = now;
    74	  wakeup(s);
