    77	// Process arrivals and I/O completions due at tick now, and open the
    78	// fairness window once every batch job is present. If a batch job
    79	// finishes before the last one arrives, the window never opens.
    80	// Caller holds wl_lock.
    81	static void
    82	events(int now)
    83	{
    84	  int i, nbatch = 0, arrived = 0, finished = 0;
    85	
    86	  for (i = 0; i < nslots; i++) {
    87	    struct wl_state *s = &ws[i];
    88	    if (s->phase == WL_WAIT && now >= s->arrive_at) {
    89	      s->st.arrival = now - start_tick;
    90	      make_ready(s, now);
    91	    } else if (s->phase == WL_IO && now >= s->io_until) {
    92	      make_ready(s, now);
    93	    }
    94	    if (isbatch(s)) {
    95	      nbatch++;
    96	      if (s->phase != WL_WAIT)
    97	        arrived++;
    98	      if (s->phase == WL_DONE)
    99	        finished++;
   100	    }
   101	  }
   102	  if (fair_start < 0 && nbatch > 1 && arrived == nbatch && finished == 0)
   103	    fair_start = now;
   104	}
