   106	// Finish the current CPU burst of slot s at tick now: start simulated
   107	// I/O, or complete the job. Caller holds wl_lock.
   108	static void
   109	advance(struct wl_state *s, int now)
   110	{
   111	  s->burst_done = 0;
   112	  s->debt = 0;
   113	  s->bursts_left--;
   114	  if (s->bursts_left > 0) {
   115	    s->phase = WL_IO;
   116	    s->io_until = now + s->def.io_burst;
   117	    return;
   118	  }
   119	  s->phase = WL_DONE;
   120	  s->st.completion = now - start_tick;
   121	  if (isbatch(s) && fair_start >= 0 && fair_end < 0)
   122	    fair_end = now;
   123	  if (++ndone == nslots)
   124	    end_tick = now;
   125	}
