   127	// Called by clockintr() on every tick, with tickslock held.
   128	// p is the process that was running during the tick that just ended.
   129	void
   130	wl_clock(struct proc *p)
   131	{
   132	  int now = ticks;
   133	
   134	  acquire(&wl_lock);
   135	  if (!loaded || !started || end_tick >= 0) {
   136	    release(&wl_lock);
   137	    return;
   138	  }
   139	
   140	  // Credit the tick that just ended.
   141	  if (p == 0) {
   142	    idle++;
   143	  } else if (p->wl_slot < 0) {
   144	    other++;
   145	  } else {
   146	    struct wl_state *s = &ws[p->wl_slot];
   147	    busy++;
   148	    if (s->phase == WL_CPU && !s->burst_done) {
   149	      int units = TICK_UNITS;
   150	      int d = s->debt < units ? s->debt : units;
   151	      s->debt -= d;
   152	      s->st.ovh_units += d;
   153	      units -= d;
   154	      if (units > s->remaining)
   155	        units = s->remaining; // the burst ended partway through the tick
   156	      s->st.cpu_units += units;
   157	      s->remaining -= units;
   158	      if (isbatch(s) && fair_start >= 0 && fair_end < 0)
   159	        s->st.fair_units += units;
   160	      if (s->remaining <= 0)
   161	        s->burst_done = 1;
   162	    }
   163	  }
   164	
   165	  events(now);
   166	  release(&wl_lock);
   167	}
