   169	// Called by the scheduler just before it switches to p, with
   170	// interrupts off. Charges the switch cost and records response time.
   171	// Does not take wl_lock: with one CPU and interrupts off, nothing
   172	// else can touch the workload state.
   173	void
   174	wl_dispatch(struct proc *p)
   175	{
   176	  int switched = (p != last_proc);
   177	
   178	  last_proc = p;
   179	  if (!loaded || !started || p->wl_slot < 0)
   180	    return;
   181	
   182	  struct wl_state *s = &ws[p->wl_slot];
   183	  s->st.dispatches++;
   184	  if (switched && s->phase == WL_CPU)
   185	    s->debt += SWITCH_COST;
   186	  if (s->ready_at >= 0) {
   187	    int lat = ticks - s->ready_at;
   188	    if (s->st.first_run < 0)
