   301	int
   302	wl_start(void)
   303	{
   304	  acquire(&wl_lock);
   305	  if (!loaded || started || myproc() != controller) {
   306	    release(&wl_lock);
   307	    return -1;
   308	  }
   309	  // Every worker must be attached and blocked in workload_checkpoint(),
   310	  // so no worker is runnable before its arrival time.
   311	  for (int i = 0; i < nslots; i++) {
   312	    struct proc *p = ws[i].p;
   313	    int asleep = 0;
   314	    if (p) {
   315	      acquire(&p->lock);
   316	      asleep = (p->state == SLEEPING);
   317	      release(&p->lock);
   318	    }
   319	    if (!asleep) {
   320	      release(&wl_lock);
   321	      return -1;
   322	    }
   323	  }
   324	  // Policy state built up while the workers were forked and attached
   325	  // depends on timing, so reset it; then every run starts the same.
   326	  sched_reset(sched_current);
   327	  started = 1;
   328	  start_tick = ticks;
   329	  last_proc = 0;
   330	  for (int i = 0; i < nslots; i++)
   331	    ws[i].arrive_at = start_tick + ws[i].def.arrival;
   332	  events(start_tick);
   333	  release(&wl_lock);
   334	  return 0;
   335	}
