   337	// Called repeatedly by a worker. Blocks while the job has not arrived
   338	// or is in simulated I/O. Returns 0 while the job needs the CPU,
   339	// 1 when the job is finished, and -1 on error.
   340	int
   341	wl_checkpoint(void)
   342	{
   343	  struct proc *p = myproc();
   344	
   345	  acquire(&wl_lock);
   346	  for (;;) {
   347	    if (!loaded || p->wl_slot < 0 || killed(p)) {
   348	      release(&wl_lock);
   349	      return -1;
   350	    }
   351	    struct wl_state *s = &ws[p->wl_slot];
   352	    if (s->burst_done)
   353	      advance(s, ticks);
   354	    if (s->phase == WL_DONE) {
   355	      release(&wl_lock);
   356	      return 1;
   357	    }
   358	    if (s->phase == WL_CPU) {
   359	      release(&wl_lock);
   360	      return 0;
   361	    }
   362	    // Not arrived yet, or in simulated I/O: block until the clock
   363	    // wakes this slot.
   364	    sleep_prepare(s);
   365	    release(&wl_lock);
   366	    sleep();
   367	    acquire(&wl_lock);
   368	  }
   369	}
