     1	#!/usr/bin/env python3
     2	"""Project 1C workload checker.
     3	
     4	Reads a workload definition file (kernel/workloads.c by default) and
     5	checks the rules that keep results meaningful:
     6	
     7	  - slot counts match, at most WL_MAXSLOTS slots, nice in [-20, 19]
     8	  - nonzero arrivals and I/O lengths are not multiples of 2, 3, or 5,
     9	    so they do not line up with common quantum boundaries (a job that
    10	    arrives exactly when a quantum expires is dispatched at once, which
    11	    hides the scheduler's real response time)
    12	  - whether fairness can be measured: every batch job must be present
    13	    at once, so the last batch arrival must come before any batch job
    14	    could finish
    15	
    16	Examples:
    17	  python3 tools/check_workloads.py
    18	  python3 tools/check_workloads.py kernel/workloads.c
    19	"""
    20	import re
    21	import sys
    22	
    23	MAXSLOTS = 16
    24	QUANTUM_FACTORS = (2, 3, 5)
    25	
    26	DEF_RE = re.compile(r'\{\s*(\d+)\s*,\s*"([^"]*)"\s*,\s*(\d+)\s*,\s*\{(.*?)\}\s*\}', re.S)
    27	SLOT_RE = re.compile(r'\{\s*(-?\d+)\s*,\s*(-?\d+)\s*,\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)\s*\}')
    28	
    29	
    30	def aligned(v):
    31	    return v > 0 and any(v % f == 0 for f in QUANTUM_FACTORS)
    32	
    33	
    34	def check(path):
    35	    src = re.sub(r"//[^\n]*", "", open(path).read())
    36	    errors = 0
    37	    seen = set()
    38	    for m in DEF_RE.finditer(src):
    39	        wid, name, n = int(m.group(1)), m.group(2), int(m.group(3))
    40	        slots = [tuple(map(int, s)) for s in SLOT_RE.findall(m.group(4))]
    41	        problems, notes = [], []
    42	        if wid in seen:
    43	            problems.append("duplicate id")
    44	        seen.add(wid)
    45	        if n != len(slots):
    46	            problems.append("nslots is %d but %d slots are listed" % (n, len(slots)))
    47	        if not 1 <= len(slots) <= MAXSLOTS:
    48	            problems.append("needs 1-%d slots" % MAXSLOTS)
    49	        for i, (arr, nice, cpu, io, rep) in enumerate(slots):
    50	            if not -20 <= nice <= 19:
    51	                problems.append("slot %d: nice %d out of range" % (i, nice))
    52	            if cpu < 1 or rep < 1 or arr < 0:
    53	                problems.append("slot %d: bad arrival, cpu_burst, or repeats" % i)
    54	            if (io == 0) != (rep == 1):
    55	                problems.append("slot %d: batch jobs need io 0 and repeats 1; "
    56	                                "interactive jobs need both > 0" % i)
    57	            if aligned(arr):
    58	                problems.append("slot %d: arrival %d is a multiple of 2, 3, or 5" % (i, arr))
    59	            if aligned(io):
    60	                problems.append("slot %d: I/O %d is a multiple of 2, 3, or 5" % (i, io))
    61	
    62	        batch = [(a, c) for a, _, c, io, r in slots if io == 0 and r == 1]
    63	        if len(batch) < 2:
    64	            notes.append("fairness n/a (fewer than 2 batch jobs)")
    65	        else:
    66	            last = max(a for a, _ in batch)
    67	            first_done = min(a + c for a, c in batch)
    68	            if last <= first_done:
    69	                notes.append("fairness window opens at tick %d" % last)
    70	            else:
    71	                notes.append("fairness n/a for preemptive schedulers (a batch "
    72	                             "job can finish by %d, last arrives at %d)" % (first_done, last))
    73	        cpu = sum(c * r for _, _, c, _, r in slots)
    74	        span = max(a + c * r + io * (r - 1) for a, _, c, io, r in slots)
    75	        notes.append("%d batch, %d interactive, %d ticks of CPU, at least %d ticks long"
    76	                     % (len(batch), len(slots) - len(batch), cpu, max(cpu, span)))
    77	
    78	        print("workload %d (%s): %s" % (wid, name, "FAIL" if problems else "ok"))
    79	        for p in problems:
    80	            print("  error:", p)
    81	        for p in notes:
    82	            print("  note:", p)
    83	        errors += len(problems)
    84	    if not seen:
    85	        print("no workloads found in", path)
    86	        errors += 1
    87	    return errors
    88	
    89	
    90	if __name__ == "__main__":
    91	    paths = sys.argv[1:] or ["kernel/workloads.c"]
    92	    sys.exit(1 if sum(check(p) for p in paths) else 0)

