//     to treat a process.
//  5. policy_init(id) may be called more than once for the same ID,
//     including at the start of every workload run. Each call must
//     reset all of the scheduler's global state.
//  6. Do not modify the protected files (kernel/workload.c,
//     kernel/workload.h, user/wl.c).

#include "types.h"
#include "param.h"
#include "memlayout.h"
#include "riscv.h"
#include "spinlock.h"
#include "proc.h"
#include "defs.h"

#define SCHED_RR     0 // round robin, 10-tick (100 ms) quantum: stock xv6
#define SCHED_RR1    1 // round robin, 1-tick (10 ms) quantum
#define SCHED_PRIO   2 // strict priority by nice (Project 1B), 10-tick quantum
#define SCHED_MLFQ   3 // multi-level feedback queues, Q2 highest
#define SCHED_STRIDE 4 // deterministic nice-weighted proportional share
#define SCHED_RR5    6 // round robin, 5-tick (50 ms) quantum

// Linux CFS weights for nice -20 .. 19, indexed by nice + 20
// (nice 0 has weight 1024). This is the same table user/wl.c uses
// for the fairness metric. For example, a fair-share scheduler can
// advance a process's vrt by (1 << 24) / nice_weight[p->nice + 20]
// for each tick it runs.
const int nice_weight[40] = {
  88761, 71755, 56483, 46273, 36291, 29154, 23254, 18705, 14949, 11916,
  9548,  7620,  6100,  4904,  3906,  3121,  2501,  1991,  1586,  1277,
  1024,  820,   655,   526,   423,   335,   272,   215,   172,   137,
  110,   87,    70,    56,    45,    36,    29,    23,    18,    15,
};

static int quantum = 10; // ticks a process may run before preemption
static int last = -1;    // index in proc[] of the last process chosen

static const int mlfq_quantum[3] = {15, 10, 2};
static const int mlfq_allotment[3] = {0, 10, 2}; // Q0 never demotes
static int mlfq_last[3];
static uint last_boost;

#define STRIDE_SCALE (1ULL << 24)
static int stride_last = -1;
static int stride_reset_left; // per-process initializations remaining in sched_reset

// Exclude p itself, including when wakeup has already made it RUNNABLE.
static int
stride_min_other(struct proc *p, uint64 *minimum)
{
  int found = 0;

  for (struct proc *q = proc; q < &proc[NPROC]; q++) {
    if (q == p || (q->state != RUNNING && q->state != RUNNABLE))
      continue;
    if (!found || q->vrt < *minimum) {
      *minimum = q->vrt;
      found = 1;
    }
  }
  return found;
}

static void
stride_place(struct proc *p)
{
  uint64 minimum = 0;

  uint64 before = p->vrt;
  int peers = stride_min_other(p, &minimum);
  if (peers && p->vrt < minimum)
    p->vrt = minimum;
  if (logging)
    printk("stride place pid %d before %lu peers %d minimum %lu after %lu at %d\n",
           p->pid, before, peers, minimum, p->vrt, ticks);
}

// Subtract a common offset well before overflow. Active ordering is unchanged;
// obsolete sleeper credit is discarded and wakeup will clamp it to active work.
static void
stride_normalize(void)
{
  uint64 minimum = 0;

  if (!stride_min_other(0, &minimum) || minimum < (1ULL << 60))
    return;
  for (struct proc *p = proc; p < &proc[NPROC]; p++) {
    if (p->state != UNUSED)
      p->vrt = p->vrt >= minimum ? p->vrt - minimum : 0;
  }
}

static int
starting_queue(int nice)
{
  if (nice <= -10)
    return 2;
  if (nice <= 10)
    return 1;
  return 0;
}

static void
change_queue(struct proc *p, int level)
{
  int old = p->level;

  p->level = level;
  if (logging && old != level)
    printk("mlfq pid %d Q%d -> Q%d at %d\n", p->pid, old, level, ticks);
}

// Called with interrupts off, including from selection after an idle interval.
static void
mlfq_boost(void)
{
  uint now = ticks;

  if (now - last_boost < 60)
    return;
  last_boost = now;
  for (struct proc *p = proc; p < &proc[NPROC]; p++) {
    if (p->state == UNUSED || p->state == ZOMBIE)
      continue;
    int old_level = p->level;
    int old_used = p->used;
    change_queue(p, p->start_level > 1 ? p->start_level : 1);
    p->used = 0; // refresh the allotment even if the queue did not change
    if (logging)
      printk("mlfq boostcheck pid %d level %d->%d used %d->%d at %d\n",
             p->pid, old_level, p->level, old_used, p->used, ticks);
  }
}

// Called by set_scheduler(id), and again when a workload starts.
// Set up global state for policy id.
// Return 0 if id is a known policy, -1 otherwise.
int
policy_init(int id)
{
  switch (id) {
  case SCHED_RR:
  case SCHED_PRIO:
    quantum = 10;
    break;
  case SCHED_RR1:
    quantum = 1;
    break;
  case SCHED_MLFQ:
  case SCHED_STRIDE:
    break;
  case SCHED_RR5:
    quantum = 5;
    break;
  default:
    return -1;
  }
  last = -1;
  for (int level = 0; level < 3; level++)
    mlfq_last[level] = -1;
  last_boost = ticks;
  stride_last = -1;
  stride_reset_left = 0;
  // sched_reset calls policy_proc_init once per allocated process with
  // interrupts off. Suppress placement until all old passes are cleared.
  if (id == SCHED_STRIDE)
    for (struct proc *p = proc; p < &proc[NPROC]; p++)
      if (p->state != UNUSED)
        stride_reset_left++;
  return 0;
}

// Called when a process is created, and for every process when the
// policy changes or a workload starts. Initialize any per-process
// policy fields.
void
policy_proc_init(struct proc *p)
{
  p->qticks = 0;
  // Level 0 is the lowest queue (Q0); Q2 is the highest. An MLFQ must
  // set the starting level from p->nice here: workload_start() calls
  // this for every process after the jobs' nice values are set.
  p->start_level = starting_queue(p->nice);
  p->level = sched_current == SCHED_MLFQ ? p->start_level : 0;
  p->used = 0;
  p->vrt = 0;
  if (sched_current == SCHED_STRIDE) {
    if (stride_reset_left > 0)
      stride_reset_left--;
    else
      stride_place(p); // new process joins at the other active minimum
  }
}

// Round robin: the next RUNNABLE process after the last one chosen,
// scanning proc[] in a circle so no process is starved.
static struct proc *
pick_rr(void)
{
  for (int i = 1; i <= NPROC; i++) {
    struct proc *p = &proc[(last + i) % NPROC];
    if (p->state == RUNNABLE) {
      last = p - proc;
      return p;
    }
  }
  return 0;
}

// Strict priority: a RUNNABLE process with the lowest nice value;
// processes with equal nice take turns in round-robin order.
static struct proc *
pick_prio(void)
{
  int best = 100;

  for (struct proc *p = proc; p < &proc[NPROC]; p++)
    if (p->state == RUNNABLE && p->nice < best)
      best = p->nice;
  for (int i = 1; i <= NPROC; i++) {
    struct proc *p = &proc[(last + i) % NPROC];
    if (p->state == RUNNABLE && p->nice == best) {
      last = p - proc;
      return p;
    }
  }
  return 0;
}

static struct proc *
pick_mlfq(void)
{
  mlfq_boost();
  for (int level = 2; level >= 0; level--) {
    for (int i = 1; i <= NPROC; i++) {
      struct proc *p = &proc[(mlfq_last[level] + i) % NPROC];
      if (p->state == RUNNABLE && p->level == level) {
        mlfq_last[level] = p - proc;
        return p;
      }
    }
  }
  return 0;
}

static struct proc *
pick_stride(void)
{
  struct proc *best = 0;

  for (int i = 1; i <= NPROC; i++) {
    struct proc *p = &proc[(stride_last + i) % NPROC];
    // Strict comparison retains circular order among equal passes.
    if (p->state == RUNNABLE && (!best || p->vrt < best->vrt))
      best = p;
  }
  if (best)
    stride_last = best - proc;
  return best;
}

// Choose the next process to run, or return 0 if none is RUNNABLE.
struct proc *
policy_pick_next_proc(void)
{
  switch (sched_current) {
  case SCHED_STRIDE:
    return pick_stride();
  case SCHED_MLFQ:
    return pick_mlfq();
  case SCHED_PRIO:
    return pick_prio();
  default:
    return pick_rr();
  }
}

// Called just before the framework switches to p.
void
policy_dispatch(struct proc *p)
{
  p->qticks = 0; // a new quantum starts
  if (logging && sched_current == SCHED_STRIDE)
    printk("stride dispatch pid %d nice %d pass %lu at %d\n",
           p->pid, p->nice, p->vrt, ticks);
}

// Called on every timer tick while p is running.
// Return 1 to preempt p, or 0 to let it keep running.
// A process is charged only for ticks that arrive while it is running.
// A loop of pause(1) wakes at a tick, runs briefly, and sleeps again
// before the next one, so it is never charged and cannot test a rule
// such as an allotment kept across sleeps. A test that is charged must
// keep the CPU across a tick, for example by spinning until uptime()
// changes before each pause(1); workload jobs are charged correctly.
int
policy_tick(struct proc *p)
{
  if (sched_current == SCHED_STRIDE) {
    p->qticks++;
    uint64 before = p->vrt;
    uint64 stride = STRIDE_SCALE / nice_weight[p->nice + 20];
    p->vrt += stride;
    if (logging)
      printk("stride charge pid %d nice %d before %lu step %lu after %lu at %d\n",
             p->pid, p->nice, before, stride, p->vrt, ticks);
    stride_normalize();
    return 1; // reconsider minimum pass after each charged tick
  }
  if (sched_current != SCHED_MLFQ) {
    p->qticks++;
    return p->qticks >= quantum;
  }

  // Charge first, then boost, then check allotment/quantum and higher queues.
  p->used++;
  p->qticks++;
  mlfq_boost();

  int preempt = 0;
  if (p->level > 0 && p->used >= mlfq_allotment[p->level]) {
    change_queue(p, p->level - 1);
    p->used = 0;
    preempt = 1;
  }
  if (p->qticks >= mlfq_quantum[p->level])
    preempt = 1;
  for (struct proc *q = proc; q < &proc[NPROC]; q++)
    if (q->state == RUNNABLE && q->level > p->level)
      preempt = 1;
  return preempt;
}

// Called when p wakes from sleep (for example, when its simulated I/O
// or a pause() ends) and becomes RUNNABLE again. Use it to decide how
// a waking process re-enters the policy; for example, a fair-share or
// stride policy may move a process that slept a long time up to the
// current minimum, so it cannot claim the CPU for the time it slept.
void
policy_wakeup(struct proc *p)
{
  if (sched_current == SCHED_STRIDE)
    stride_place(p);
  // MLFQ retains level and used across sleeps; dispatch resets only qticks.
}

// Called whenever p's nice value changes.
void
policy_nice(struct proc *p)
{
  // Stride derives its increment from the current nice; preserve its pass.
  if (sched_current != SCHED_MLFQ)
    return;
  int old_start = p->start_level;
  int old_level = p->level;
  int old_used = p->used;
  int old_qticks = p->qticks;
  int start = starting_queue(p->nice);
  if (start != p->start_level) {
    p->start_level = start;
    change_queue(p, start);
    p->used = 0;
  }
  // Diagnostics observe Rule 6 without changing scheduling decisions.
  if (logging)
    printk("mlfq nicecheck pid %d nice %d start %d->%d level %d->%d used %d->%d qticks %d->%d at %d\n",
           p->pid, p->nice, old_start, p->start_level, old_level, p->level,
           old_used, p->used, old_qticks, p->qticks, ticks);
}

