// Called by set_scheduler(id), and again when a workload starts.
// Set up global state for policy id.
// Return 0 if id is a known policy, -1 otherwise.
int
policy_init(int id)
{
  // Select into locals first: an invalid ID must not alter the active policy.
  int next_quantum = 10;
  int next_stride_quantum = 1;
  int next_ticket_floor = 0;
  uint next_boost_interval = 60;
  int next_q0_quantum = 15;

  switch (id) {
  case SCHED_RR:
  case SCHED_PRIO:
  case SCHED_MLFQ:
  case SCHED_STRIDE:
    break;
  case SCHED_RR1:
    next_quantum = 1;
    break;
  case SCHED_RR5:
    next_quantum = 5;
    break;
  case SCHED_STRIDE5:
    next_stride_quantum = 5;
    break;
  case SCHED_STRIDE_FLOOR:
    next_ticket_floor = 335;
    break;
  case SCHED_MLFQ_BOOST30:
    next_boost_interval = 30;
    break;
  case SCHED_MLFQ_Q030:
    next_q0_quantum = 30;
    break;
  default:
    return -1;
  }
  // Reset every configurable parameter on each successful selection.
  quantum = next_quantum;
  stride_quantum = next_stride_quantum;
  stride_ticket_floor = next_ticket_floor;
  mlfq_boost_interval = next_boost_interval;
  mlfq_quantum[0] = next_q0_quantum;
  mlfq_quantum[1] = 10;
  mlfq_quantum[2] = 2;
  last = -1;
  for (int level = 0; level < 3; level++)
    mlfq_last[level] = -1;
  last_boost = ticks;
  stride_last = -1;
  stride_reset_left = 0;
  // sched_reset calls policy_proc_init once per allocated process with
  // interrupts off. Suppress placement until all old passes are cleared.
  if (is_stride(id))
    for (struct proc *p = proc; p < &proc[NPROC]; p++)
      if (p->state != UNUSED)
        stride_reset_left++;
  return 0;
}

// Called when a process is created, and for every process when the
// policy changes or a workload starts. Initialize any per-process
// policy fields.
void
policy_proc_init(struct proc *p)
{
  p->qticks = 0;
  // Level 0 is the lowest queue (Q0); Q2 is the highest. An MLFQ must
  // set the starting level from p->nice here: workload_start() calls
  // this for every process after the jobs' nice values are set.
  p->start_level = starting_queue(p->nice);
  p->level = is_mlfq(sched_current) ? p->start_level : 0;
  p->used = 0;
  p->vrt = 0;
  if (is_stride(sched_current)) {
    if (stride_reset_left > 0)
      stride_reset_left--;
    else
      stride_place(p); // new process joins at the other active minimum
  }
}

