static struct proc *
pick_stride(void)
{
  struct proc *best = 0;

  for (int i = 1; i <= NPROC; i++) {
    struct proc *p = &proc[(stride_last + i) % NPROC];
    // Strict comparison retains circular order among equal passes.
    if (p->state == RUNNABLE && (!best || p->vrt < best->vrt))
      best = p;
  }
  if (best)
    stride_last = best - proc;
  return best;
}

// Choose the next process to run, or return 0 if none is RUNNABLE.
struct proc *
policy_pick_next_proc(void)
{
  switch (sched_current) {
  case SCHED_STRIDE:
  case SCHED_STRIDE5:
  case SCHED_STRIDE_FLOOR:
    return pick_stride();
  case SCHED_MLFQ:
  case SCHED_MLFQ_BOOST30:
  case SCHED_MLFQ_Q030:
    return pick_mlfq();
  case SCHED_PRIO:
    return pick_prio();
  default:
    return pick_rr();
  }
}

// Called just before the framework switches to p.
void
policy_dispatch(struct proc *p)
{
  p->qticks = 0; // a new quantum starts
  if (logging && is_stride(sched_current))
    printk("stride dispatch pid %d nice %d pass %lu at %d\n",
           p->pid, p->nice, p->vrt, ticks);
}

// Called on every timer tick while p is running.
// Return 1 to preempt p, or 0 to let it keep running.
// A process is charged only for ticks that arrive while it is running.
// A loop of pause(1) wakes at a tick, runs briefly, and sleeps again
// before the next one, so it is never charged and cannot test a rule
// such as an allotment kept across sleeps. A test that is charged must
// keep the CPU across a tick, for example by spinning until uptime()
// changes before each pause(1); workload jobs are charged correctly.
int
policy_tick(struct proc *p)
{
  if (is_stride(sched_current)) {
    p->qticks++;
    uint64 before = p->vrt;
    int tickets = nice_weight[p->nice + 20];
    if (tickets < stride_ticket_floor)
      tickets = stride_ticket_floor;
    uint64 stride = STRIDE_SCALE / tickets;
    p->vrt += stride;
    if (logging)
      printk("stride charge pid %d nice %d before %lu step %lu after %lu at %d\n",
             p->pid, p->nice, before, stride, p->vrt, ticks);
    stride_normalize();
    return p->qticks >= stride_quantum;
  }
  if (!is_mlfq(sched_current)) {
    p->qticks++;
    return p->qticks >= quantum;
  }

  // Charge first, then boost, then check allotment/quantum and higher queues.
  p->used++;
  p->qticks++;
  mlfq_boost();

  int preempt = 0;
  if (p->level > 0 && p->used >= mlfq_allotment[p->level]) {
    change_queue(p, p->level - 1);
    p->used = 0;
    preempt = 1;
  }
  if (p->qticks >= mlfq_quantum[p->level])
    preempt = 1;
  for (struct proc *q = proc; q < &proc[NPROC]; q++)
    if (q->state == RUNNABLE && q->level > p->level)
      preempt = 1;
  return preempt;
}

// Called when p wakes from sleep (for example, when its simulated I/O
// or a pause() ends) and becomes RUNNABLE again. Use it to decide how
// a waking process re-enters the policy; for example, a fair-share or
// stride policy may move a process that slept a long time up to the
// current minimum, so it cannot claim the CPU for the time it slept.
void
policy_wakeup(struct proc *p)
{
  if (is_stride(sched_current))
    stride_place(p);
  // MLFQ retains level and used across sleeps; dispatch resets only qticks.
}

// Called whenever p's nice value changes.
void
policy_nice(struct proc *p)
{
  // Stride derives its increment from the current nice; preserve its pass.
  if (!is_mlfq(sched_current))
    return;
  int old_start = p->start_level;
  int old_level = p->level;
  int old_used = p->used;
  int old_qticks = p->qticks;
  int start = starting_queue(p->nice);
  if (start != p->start_level) {
    p->start_level = start;
    change_queue(p, start);
    p->used = 0;
  }
  // Diagnostics observe Rule 6 without changing scheduling decisions.
  if (logging)
    printk("mlfq nicecheck pid %d nice %d start %d->%d level %d->%d used %d->%d qticks %d->%d at %d\n",
           p->pid, p->nice, old_start, p->start_level, old_level, p->level,
           old_used, p->used, old_qticks, p->qticks, ticks);
}
  // Project 1C: per-process state for scheduling policies.
  // Add any fields your policies need here, and initialize them
  // in policy_proc_init() in policy.c.
  int qticks; // ticks used in the current quantum
  int level;  // queue level, for multi-level policies
  int start_level; // nice-based starting queue, retained across demotions/boosts
  int used;   // ticks used at the current level (allotment)
  uint64 vrt; // weighted CPU usage, for fair-share policies

  // Project 1C: workload harness slot, or -1 if not a worker.
  // Owned by workload.c; do not modify.
  int wl_slot;
};

